#!/usr/bin/env node

/**
 * Snapshot `dashboard/supabase/migrations/*.sql` into a TS manifest that
 * the runtime can import. The migration files themselves are not bundled
 * into the Next.js output (they live outside src/), so the drift-detector
 * cron needs a build-time projection of {version, name} pairs to compare
 * against `supabase_migrations.schema_migrations` in prod.
 *
 * Intentionally vanilla Node (no deps). Runs from `prebuild` so the
 * generated file is always fresh on `npm run build`. It is also wired
 * into `predev` and `pretypecheck` so local edits keep the manifest in
 * sync without operator action.
 *
 * The output file is committed — readers can grep it, CI compares it,
 * and a deploy never ships a stale manifest just because someone forgot
 * to run a generator.
 */

const fs = require("fs");
const path = require("path");

const DASHBOARD_ROOT = path.resolve(__dirname, "..");
const MIGRATIONS_DIR = path.join(DASHBOARD_ROOT, "supabase/migrations");
const OUTPUT_PATH = path.join(
  DASHBOARD_ROOT,
  "src/lib/generated/migrations-manifest.ts"
);

const FILENAME_RE = /^(\d{14})_(.+)\.sql$/;

function loadMigrations() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    throw new Error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
  }

  const entries = fs.readdirSync(MIGRATIONS_DIR);
  const migrations = [];

  for (const entry of entries) {
    const match = FILENAME_RE.exec(entry);
    if (!match) {
      if (entry.endsWith(".sql")) {
        // Don't silently skip malformed names — drift detection depends
        // on the version/name split, and a typo'd filename would create
        // a phantom "always missing" row in prod.
        throw new Error(
          `Migration filename does not match <14-digit-version>_<name>.sql: ${entry}`
        );
      }
      continue;
    }
    migrations.push({ version: match[1], name: match[2] });
  }

  migrations.sort((a, b) => a.version.localeCompare(b.version));
  return migrations;
}

function renderManifest(migrations) {
  const lines = [
    "// Auto-generated by scripts/generate-migrations-manifest.cjs.",
    "// Do not edit by hand. Run `node scripts/generate-migrations-manifest.cjs`",
    "// (also runs automatically via `prebuild` / `predev` / `pretypecheck`).",
    "",
    "export interface LocalMigrationEntry {",
    "  version: string;",
    "  name: string;",
    "}",
    "",
    "export const LOCAL_MIGRATIONS: readonly LocalMigrationEntry[] = [",
  ];

  for (const m of migrations) {
    lines.push(
      `  { version: ${JSON.stringify(m.version)}, name: ${JSON.stringify(m.name)} },`
    );
  }

  lines.push("];", "");
  return lines.join("\n");
}

function main() {
  const migrations = loadMigrations();
  const rendered = renderManifest(migrations);

  fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });

  let existing = "";
  try {
    existing = fs.readFileSync(OUTPUT_PATH, "utf8");
  } catch {
    existing = "";
  }

  if (existing === rendered) {
    console.log(
      `[migrations-manifest] no changes (${migrations.length} migrations)`
    );
    return;
  }

  fs.writeFileSync(OUTPUT_PATH, rendered);
  console.log(
    `[migrations-manifest] wrote ${migrations.length} migrations → ${path.relative(DASHBOARD_ROOT, OUTPUT_PATH)}`
  );
}

main();
